def parse():
    out = []
    for ln in RAW.strip().split('\n'):
        key, name, cat, gen, eras = ln.split('|')
        es = []
        for e in eras.split(';;'):
            d, t = e.split('=', 1); es.append((d.strip(), t.strip()))
        out.append(dict(key=key, name=name, cat=cat, genres=gen.split(','), eras=es))
    return out
